<script setup>
import {reactive,ref,useId} from 'vue';import {dispatch} from '../state';import {t,errorText} from '../i18n';import {quantity} from '../../core/shared.mjs';import {forecastSettings,FORECAST_KINDS} from '../../core/project-forecast.mjs';import AppDialog from './AppDialog.vue';import FormField from './FormField.vue';
const props=defineProps({project:Object,structured:Boolean}),emit=defineEmits(['close','saved']),initial=forecastSettings(props.project.settings.forecast??{}),formId=useId(),operation=crypto.randomUUID(),busy=ref(false),error=ref('');const draft=reactive({method:initial.method,weeklyHours:initial.weeklyHours??'',extraMinutes:initial.extraMinutes,remaining:{...initial.manualRemaining}}),rates=reactive(Object.fromEntries(FORECAST_KINDS.map(k=>[k,{seconds:initial.manualSeconds[k],text:initial.manualSeconds[k]??'',unit:'seconds',edited:false}])));
function seconds(row){if(!row.edited)return row.seconds;const n=quantity(row.text,{nullable:true});return n===null?null:n*(row.unit==='minutes'?60:1)}
function unit(kind,event){const row=rates[kind],value=event.target.value;try{const n=seconds(row);row.seconds=n;row.unit=value;row.text=n===null?'':n/(value==='minutes'?60:1);row.edited=false;error.value=''}catch(caught){error.value=errorText(caught);event.target.value=row.unit}}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{await dispatch('project.forecastSettings',{projectId:props.project.id,method:draft.method,weeklyHours:draft.weeklyHours,extraMinutes:draft.extraMinutes,manualSeconds:draft.method==='manual'?Object.fromEntries(FORECAST_KINDS.map(k=>[k,seconds(rates[k])])):{...initial.manualSeconds},manualRemaining:draft.method==='manual'?{...draft.remaining}:{...initial.manualRemaining}},operation);emit('saved')}catch(caught){error.value=errorText(caught)}finally{busy.value=false}}
</script>
<template><AppDialog :title="t('forecastAssumptions')" :busy="busy" wide @close="emit('close')"><p v-if="error" role="alert" class="notice error">{{error}}</p><form :id="formId" @submit.prevent="save"><div class="form-grid"><FormField :label="t('forecastMethod')" required wide v-slot="{id}"><select :id="id" v-model="draft.method"><option value="measured">{{t('forecastMeasured')}}</option><option value="manual">{{t('forecastManual')}}</option></select></FormField><p class="field-help field-wide">{{t(draft.method==='manual'?'forecastManualHelp':'forecastMeasuredHelp')}}</p><template v-if="draft.method==='manual'"><p class="notice field-wide">{{t(structured?'forecastGridCounts':'forecastManualCountsHelp')}}</p><template v-for="kind in FORECAST_KINDS" :key="kind"><FormField :label="t('forecastRateFor',{kind:t(`workKind_${kind}`)})" v-slot="{id}"><input :id="id" v-model="rates[kind].text" inputmode="decimal" :placeholder="t('unknown')" @input="rates[kind].edited=true"/></FormField><FormField :label="t('forecastUnitFor',{kind:t(`workKind_${kind}`)})" v-slot="{id}"><select :id="id" :value="rates[kind].unit" @change="unit(kind,$event)"><option value="seconds">{{t('seconds')}}</option><option value="minutes">{{t('minutes')}}</option></select></FormField><FormField v-if="!structured" :label="t('forecastRemainingFor',{kind:t(`workKind_${kind}`)})" wide v-slot="{id}"><input :id="id" v-model="draft.remaining[kind]" inputmode="numeric" :placeholder="t('unknown')"/></FormField></template></template><FormField :label="t('weeklyAvailableHours')" :help="t('forecastWeeklyHelp')" v-slot="{id,describedby}"><input :id="id" v-model="draft.weeklyHours" inputmode="decimal" :aria-describedby="describedby"/></FormField><FormField :label="t('extraFinishingMinutes')" required v-slot="{id}"><input :id="id" v-model="draft.extraMinutes" required inputmode="decimal"/></FormField></div></form><template #footer><button class="button" :disabled="busy" @click="emit('close')">{{t('cancel')}}</button><button class="button primary" type="submit" :form="formId" :disabled="busy">{{t(busy?'saving':'save')}}</button></template></AppDialog></template>
